<script setup>
import { ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import api from '../api'
const router=useRouter(),sidebarOpen=ref(false),notificationsOn=ref(true),emailAlertsOn=ref(true),showEditModal=ref(false),showPasswordModal=ref(false)
const profile=ref({name:'Jose Enrique',studentId:'2023-1045',email:'joseenrique@liceo.edu.ph',department:'Information Technology',yearLevel:'2nd Year',memberSince:'Jan 2023',itemsFound:5,returned:3,active:2}),activePosts=ref([])
const editForm=ref({fullName:'Jose Enrique',studentId:'2023-1045',email:'joseenrique@liceo.edu.ph',department:'Information Technology',yearLevel:'2nd Year',phone:'+63 912 345 6789',address:'Cagayan de Oro City, Misamis Oriental'}),passwordForm=ref({current:'',newPass:'',confirm:''})
const saveProfile=async()=>{try{await api.put('/users/me',{full_name:editForm.value.fullName,email:editForm.value.email,department:editForm.value.department,year_level:editForm.value.yearLevel,phone:editForm.value.phone,address:editForm.value.address});profile.value={...profile.value,name:editForm.value.fullName,email:editForm.value.email,department:editForm.value.department,yearLevel:editForm.value.yearLevel};showEditModal.value=false;alert('Profile updated successfully!')}catch{alert('Failed to update profile.')}}
const logout=()=>{localStorage.removeItem('access_token');router.push('/login')}
</script>
