Modal" class="modal-overlay" @click="showEditModal=false"></div><div v-if="showEditModal" class="modal"><h3>Edit Profile</h3><div class="edit-modal-body"><div class="fg"><label>Full Name</label><input v-model="editForm.fullName"/></div><div class="fg"><label>Student ID</label><input v-model="editForm.studentId" disabled/></div><div class="fg"><label>Email Address</label><input v-model="editForm.email"/></div><div class="fg"><label>Department</label><input v-model="editForm.department"/></div><div class="fg"><label>Year Level</label><input v-model="editForm.yearLevel"/></div></div><div class="modal-footer"><button class="btn-cancel" @click="showEditModal=false">Cancel</button><button class="btn-save" @click="saveProfile">Save Changes</button></div></div><div v-if="showPasswordModal" class="modal"><h3>Change Password</h3><div class="edit-modal-body"><input v-model="passwordForm.current" type="password" placeholder="Current Password"/><input v-model="passwordForm.newPass" type="password" placeholder="New Password"/><input v-model="passwordForm.confirm" type="password" placeholder="Confirm New Password"/></div><div class="modal-footer"><button class="btn-cancel" @click="showPasswordModal=false">Cancel</button><button class="btn-save" @click="showPasswordModal=false">Update Password</button></div></div></div></template>
